// unmarshalPermissionInfoResponseBodyToUserviewsPermissionInfoView builds a
// value of type *userviews.PermissionInfoView from a value of type
// *PermissionInfoResponseBody.
func unmarshalPermissionInfoResponseBodyToUserviewsPermissionInfoView(v *PermissionInfoResponseBody) *userviews.PermissionInfoView {
	res := &userviews.PermissionInfoView{
		Resource:   v.Resource,
		Effect:     v.Effect,
		SourceRole: v.SourceRole,
	}
	action := userviews.ActionTypeView(*v.Action)
	res.Action = &action
	if v.Conditions != nil {
		res.Conditions = make(map[string]any, len(v.Conditions))
		for key, val := range v.Conditions {
			tk := key
			tv := val
			res.Conditions[tk] = tv
		}
	}

	return res
}
